-- Regenerate after changing the synthetic data model or defect profile.

{{ config(
    materialized='view'
) }}

with source as (
    select * from {{ source('lake_facts', 'fact_tank_dips') }}
),

-- Stage 1: repair. Trim, case-fold, parse numbers out of
-- locale-formatted text, range-check timestamps.
cleansed as (
    select
        {{ clean_code('tank_dip_id') }} as tank_dip_id,
        {{ clean_timestamp('dip_ts') }} as dip_ts,
        {{ clean_integer('date_key') }} as date_key,
        {{ clean_code('tank_id') }} as tank_id,
        {{ clean_code('site_id') }} as site_id,
        {{ clean_code('product_id') }} as product_id,
        {{ clean_integer('capacity_litres') }} as capacity_litres,
        {{ correct_unit_error(clean_measure('volume_litres'), 3000000) }} as volume_litres,
        {{ clean_measure('ullage_litres') }} as ullage_litres,
        {{ clean_measure('fill_pct') }} as fill_pct,
        {{ clean_measure('water_level_mm') }} as water_level_mm,
        {{ clean_measure('temperature_celsius') }} as temperature_celsius,
        try_cast(below_reorder_point as boolean) as below_reorder_point,
        {{ fix_mojibake('reading_source') }} as reading_source,
        {{ clean_code('source_system_code') }} as source_system_code,
        {{ clean_timestamp('ingested_at') }} as ingested_at,
        1 as _dummy
    from source
),

-- Stage 2: assess. One boolean per rule, so a quarantined
-- row records exactly why it was rejected.
assessed as (
    select
        *,
        (tank_dip_id is not null) as _dq_tank_dip_id_present,
        (site_id is not null) as _dq_site_id_present,
        (product_id is not null) as _dq_product_id_present,
        (dip_ts is not null) as _dq_event_timestamp_valid,
        (volume_litres >= 0) as _dq_volume_litres_non_negative,
        (volume_litres <= 3000000) as _dq_volume_litres_within_range,
        (coalesce(_dq_tank_dip_id_present, false) and coalesce(_dq_site_id_present, false) and coalesce(_dq_product_id_present, false) and coalesce(_dq_event_timestamp_valid, false) and coalesce(_dq_volume_litres_non_negative, false) and coalesce(_dq_volume_litres_within_range, false)) as _dq_is_valid,
        concat_ws(',',
            case when not coalesce(_dq_tank_dip_id_present, false) then 'tank_dip_id_present' end,
            case when not coalesce(_dq_site_id_present, false) then 'site_id_present' end,
            case when not coalesce(_dq_product_id_present, false) then 'product_id_present' end,
            case when not coalesce(_dq_event_timestamp_valid, false) then 'event_timestamp_valid' end,
            case when not coalesce(_dq_volume_litres_non_negative, false) then 'volume_litres_non_negative' end,
            case when not coalesce(_dq_volume_litres_within_range, false) then 'volume_litres_within_range' end
        ) as _dq_failed_rules
    from cleansed
),

-- Stage 3: deduplicate. Source systems replay batches, so
-- the same business key can arrive more than once. Keep the
-- most recently ingested version.
deduplicated as (
    select
        *,
        row_number() over (partition by tank_dip_id order by ingested_at desc nulls last) as _row_rank
    from assessed
    where _dq_is_valid
)

select
    tank_dip_id,
    dip_ts,
    date_key,
    tank_id,
    site_id,
    product_id,
    capacity_litres,
    volume_litres,
    ullage_litres,
    fill_pct,
    water_level_mm,
    temperature_celsius,
    below_reorder_point,
    reading_source,
    source_system_code,
    ingested_at,
    {{ cleansing_layer_columns() }}
from deduplicated
where _row_rank = 1
